-- Blocks of two or more narrow-range integer GROUP BY keys are aggregated through a directly indexed array:
-- each check compares the result with the same query under aggregation_direct_index_max_cells = 0.

SELECT '1 UInt16 x UInt8, count', (SELECT sum(cityHash64(a, b, c)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '2 UInt16 x UInt8, states', (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '3 one thread, count', (SELECT sum(cityHash64(a, b, c)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c FROM numbers(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1))
    = (SELECT sum(cityHash64(a, b, c)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c FROM numbers(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1, aggregation_direct_index_max_cells = 0));
SELECT '4 Int64 x Int32, negative', (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT toInt64(-5000000000 + intHash32(number) % 10) AS a, toInt32(-100000 + intHash32(number + 1) % 30) AS b, count() AS c, sum(number) AS s FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT toInt64(-5000000000 + intHash32(number) % 10) AS a, toInt32(-100000 + intHash32(number + 1) % 30) AS b, count() AS c, sum(number) AS s FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '5 UInt64 x UInt32, top of the range', (SELECT sum(cityHash64(a, b, c)) FROM (SELECT bitNot(toUInt64(intHash32(number) % 40)) AS a, toUInt32(4000000000 + intHash32(number + 1) % 10) AS b, count() AS c FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c)) FROM (SELECT bitNot(toUInt64(intHash32(number) % 40)) AS a, toUInt32(4000000000 + intHash32(number + 1) % 10) AS b, count() AS c FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '6 Int8 x Int16, negative', (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT toInt8(-60 + intHash32(number) % 9) AS a, toInt16(-200 + intHash32(number + 1) % 40) AS b, count() AS c, sum(number) AS s FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT toInt8(-60 + intHash32(number) % 9) AS a, toInt16(-200 + intHash32(number + 1) % 40) AS b, count() AS c, sum(number) AS s FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '7 Bool x Date x Enum8, count', (SELECT sum(cityHash64(x, d, e, c)) FROM (SELECT toBool(intHash32(number) % 2) AS x, toDate('2024-01-01') + intHash32(number + 1) % 60 AS d, CAST(['x', 'y', 'z'][1 + intHash32(number + 2) % 3], 'Enum8(\'x\' = -3, \'y\' = 0, \'z\' = 5)') AS e, count() AS c FROM numbers_mt(300000) GROUP BY x, d, e SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(x, d, e, c)) FROM (SELECT toBool(intHash32(number) % 2) AS x, toDate('2024-01-01') + intHash32(number + 1) % 60 AS d, CAST(['x', 'y', 'z'][1 + intHash32(number + 2) % 3], 'Enum8(\'x\' = -3, \'y\' = 0, \'z\' = 5)') AS e, count() AS c FROM numbers_mt(300000) GROUP BY x, d, e SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '7 Bool x Date x Enum8, sum', (SELECT sum(cityHash64(x, d, e, c, s)) FROM (SELECT toBool(intHash32(number) % 2) AS x, toDate('2024-01-01') + intHash32(number + 1) % 60 AS d, CAST(['x', 'y', 'z'][1 + intHash32(number + 2) % 3], 'Enum8(\'x\' = -3, \'y\' = 0, \'z\' = 5)') AS e, count() AS c, sum(number) AS s FROM numbers_mt(300000) GROUP BY x, d, e SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(x, d, e, c, s)) FROM (SELECT toBool(intHash32(number) % 2) AS x, toDate('2024-01-01') + intHash32(number + 1) % 60 AS d, CAST(['x', 'y', 'z'][1 + intHash32(number + 2) % 3], 'Enum8(\'x\' = -3, \'y\' = 0, \'z\' = 5)') AS e, count() AS c, sum(number) AS s FROM numbers_mt(300000) GROUP BY x, d, e SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '8 compiled', (SELECT sum(cityHash64(a, b, s, mn, mx)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, sum(number) AS s, min(number) AS mn, max(number) AS mx FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, compile_aggregate_expressions = 1, min_count_to_compile_aggregate_expression = 0))
    = (SELECT sum(cityHash64(a, b, s, mn, mx)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, sum(number) AS s, min(number) AS mn, max(number) AS mx FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, compile_aggregate_expressions = 1, min_count_to_compile_aggregate_expression = 0, aggregation_direct_index_max_cells = 0));
SELECT '9 two-level, external', (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, max_bytes_before_external_group_by = 1, max_bytes_ratio_before_external_group_by = 0, group_by_two_level_threshold = 1, group_by_two_level_threshold_bytes = 1, enable_adaptive_aggregator = 0))
    = (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 4, max_bytes_before_external_group_by = 1, max_bytes_ratio_before_external_group_by = 0, group_by_two_level_threshold = 1, group_by_two_level_threshold_bytes = 1, enable_adaptive_aggregator = 0, aggregation_direct_index_max_cells = 0));
SELECT '10 mixed blocks', (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT if(intDiv(number, 65536) % 2 = 0, intHash32(number) % 50, intHash64(number)) AS a, toUInt8(number % 4) AS b, count() AS c, sum(number) AS s FROM numbers(600000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1))
    = (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT if(intDiv(number, 65536) % 2 = 0, intHash32(number) % 50, intHash64(number)) AS a, toUInt8(number % 4) AS b, count() AS c, sum(number) AS s FROM numbers(600000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1, aggregation_direct_index_max_cells = 0));
SELECT '11 one key per block', (SELECT sum(cityHash64(a, b, c, s, m)) FROM (SELECT toUInt32(intDiv(number, 65536)) AS a, toUInt8(intDiv(number, 131072) % 3) AS b, count() AS c, sum(number) AS s, avg(number) AS m FROM numbers(600000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1))
    = (SELECT sum(cityHash64(a, b, c, s, m)) FROM (SELECT toUInt32(intDiv(number, 65536)) AS a, toUInt8(intDiv(number, 131072) % 3) AS b, count() AS c, sum(number) AS s, avg(number) AS m FROM numbers(600000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1, aggregation_direct_index_max_cells = 0));
SELECT '12 totals', (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b WITH TOTALS SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b WITH TOTALS SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '12 rollup', (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b WITH ROLLUP SETTINGS max_block_size = 65536, max_threads = 4))
    = (SELECT sum(cityHash64(a, b, c, s, m, u, g)) FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c, sum(number) AS s, avg(number) AS m, uniqExact(number % 100) AS u, groupArraySorted(3)(number) AS g FROM numbers_mt(300000) GROUP BY a, b WITH ROLLUP SETTINGS max_block_size = 65536, max_threads = 4, aggregation_direct_index_max_cells = 0));
SELECT '13 days x products, count', (SELECT sum(cityHash64(d, p, c)) FROM (SELECT toDate('2024-01-01') + intDiv(number, 30000) AS d, toUInt16(intHash32(number) % 500) AS p, count() AS c FROM numbers_mt(3000000) GROUP BY d, p SETTINGS max_block_size = 65536, max_threads = 2))
    = (SELECT sum(cityHash64(d, p, c)) FROM (SELECT toDate('2024-01-01') + intDiv(number, 30000) AS d, toUInt16(intHash32(number) % 500) AS p, count() AS c FROM numbers_mt(3000000) GROUP BY d, p SETTINGS max_block_size = 65536, max_threads = 2, aggregation_direct_index_max_cells = 0));
SELECT '13 days x products, low freeze threshold', (SELECT sum(cityHash64(d, p, c, s)) FROM (SELECT toDate('2024-01-01') + intDiv(number, 30000) AS d, toUInt16(intHash32(number) % 500) AS p, count() AS c, sum(number) AS s FROM numbers_mt(3000000) GROUP BY d, p SETTINGS max_block_size = 65536, max_threads = 2, adaptive_aggregator_freeze_threshold = 100))
    = (SELECT sum(cityHash64(d, p, c, s)) FROM (SELECT toDate('2024-01-01') + intDiv(number, 30000) AS d, toUInt16(intHash32(number) % 500) AS p, count() AS c, sum(number) AS s FROM numbers_mt(3000000) GROUP BY d, p SETTINGS max_block_size = 65536, max_threads = 2, adaptive_aggregator_freeze_threshold = 100, aggregation_direct_index_max_cells = 0));
SELECT '14 overflow any', (SELECT count() FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c FROM numbers(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1, max_rows_to_group_by = 100, group_by_overflow_mode = 'any'))
    = (SELECT count() FROM (SELECT toUInt16(intHash32(number) % 60) AS a, toUInt8(intHash32(number + 1) % 7) AS b, count() AS c FROM numbers(300000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1, max_rows_to_group_by = 100, group_by_overflow_mode = 'any', aggregation_direct_index_max_cells = 0));
SELECT '15 late rejection', (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT toUInt16(if(number % 65536 < 49152, number % 20, intHash32(number) % 4000)) AS a, toUInt8(number % 2) AS b, count() AS c, sum(number) AS s FROM numbers(600000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1))
    = (SELECT sum(cityHash64(a, b, c, s)) FROM (SELECT toUInt16(if(number % 65536 < 49152, number % 20, intHash32(number) % 4000)) AS a, toUInt8(number % 2) AS b, count() AS c, sum(number) AS s FROM numbers(600000) GROUP BY a, b SETTINGS max_block_size = 65536, max_threads = 1, aggregation_direct_index_max_cells = 0));
